custom_css:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Plus+Jakarta+Sans:wght@600&family=Poppins:wght@500&display=swap');

:root{
  --black:#1C1C1C;
  --body:#474747;
  --white:#FFFFFF;
  --dark:#161A29;
  --light:#F6F6F6;
  --primary:#00758D;
  --secondary:#773DBE;
  --accent:#E01783;
  --card-text:#333333;
}

*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:'Inter',sans-serif;color:var(--black);background:var(--white)}
a{text-decoration:none;color:inherit}img{max-width:100%;display:block}

/* Design system */
.container{width:100%;max-width:1200px!important;margin-inline:auto;padding-inline:15px}
.bg-white{background:var(--white)}
.bg-light{background:var(--light)}
.bg-dark{background:radial-gradient(560px 560px at 85% 40%,rgba(224,23,131,.14),transparent 62%),radial-gradient(420px 420px at 6% 4%,rgba(119,61,190,.14),transparent 66%),var(--dark)}
.txt-white{color:var(--white)}
.txt-black{color:var(--black)}
.txt-body{color:var(--body)}
.txt-accent{color:var(--accent)}
.txt-primary{color:var(--primary)}
.section-padding{padding:80px 0}
.section-title{margin:0 0 32px;font-family:'Plus Jakarta Sans',sans-serif;font-size:40px;line-height:50px;font-weight:600;color:var(--black)}
.section-title-light{color:var(--white)}
.section-title-center{text-align:center;margin-bottom:40px}
.section-eyebrow{display:block;margin-bottom:12px;font-family:'Poppins',sans-serif;font-size:18px;line-height:27px;font-weight:500;color:var(--accent)}
.section-content{max-width:590px}
.section-content-sm{max-width:387px}
.body-text{margin:0 0 32px;font-size:16px;line-height:28px;font-weight:400;color:var(--body)}
.body-text-light{color:var(--white)}
.sub-title{margin:0 0 16px;font-size:24px;line-height:40px;font-weight:600;color:var(--black)}
.theme-btn{display:inline-flex;align-items:center;gap:20px;min-height:50px;padding:7px 7px 7px 20px;border-radius:12px;font-size:16px;line-height:19px;font-weight:500;color:var(--white);white-space:nowrap}
.theme-btn-primary{background:var(--primary)}
.theme-btn-secondary{background:var(--secondary)}
.btn-icon{width:36px;height:36px;border-radius:12px;background:var(--white);display:inline-flex;align-items:center;justify-content:center;font-size:22px;line-height:1;color:var(--primary)}
.theme-btn-secondary .btn-icon{color:var(--secondary)}
.section-image{border-radius:12px;overflow:hidden}
.section-image img{width:100%;height:100%;object-fit:cover}
.card-shadow{box-shadow:0 0 4px rgba(0,0,0,.25)}

/* Header */
.site-header{height:80px;position:sticky;top:0;z-index:50;background:var(--white)}
.logo-img{width:200px;height:58px;object-fit:contain}
.main-menu{font-size:16px;line-height:19px;color:#111}

/* Hero */
.hero-section{min-height:528px}
.hero-content{max-width:694px}
.hero-title{margin:0 0 24px;font-family:'Plus Jakarta Sans',sans-serif;font-size:55px;line-height:64px;font-weight:600;color:var(--white)}
.hero-kicker{margin:0 0 12px;font-size:18px;line-height:22px;font-weight:500;color:var(--accent)}
.hero-subtitle{margin:0 0 12px;font-size:20px;line-height:32px;color:var(--white)}
.hero-quote{margin:0 0 24px;max-width:588px;font-size:16px;line-height:32px;color:var(--white)}
.hero-image{display:flex;justify-content:flex-end}.hero-img{width:100%;max-width:527px;margin-inline:auto}

/*Below Home Hero Banner Sect*/
/* Trust bar */
.trust-bar-section{position:relative;overflow:hidden;padding:40px 0;background:var(--primary)}
.trust-bar-grid{display:flex;align-items:center;gap:100px;min-height:50px}
.trust-bar-item{display:flex;align-items:center;gap:15px;min-width:0}
.trust-bar-location{flex:0 0 563px}
.trust-bar-experience{flex:0 0 425px}
.trust-bar-icon{width:50px;height:50px;flex:0 0 50px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;background:var(--white)}
.trust-bar-icon-inner{width:44px;height:44px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;background:var(--secondary);color:var(--white)}
.trust-bar-icon svg{width:24px;height:24px;stroke:currentColor}
.trust-bar-text{margin:0;font-size:17px;line-height:28px;font-weight:500;color:var(--white)}
.trust-bar-watermark{position:absolute;right:0;top:50%;width:130px;height:130px;transform:translateY(-50%);color:var(--white);}


/* Services */
.service-card{height:400px;padding:8px 8px 0;border-radius:12px;background:var(--white);overflow:hidden}
.service-thumb{height:180px;border-radius:12px;overflow:hidden}
.service-thumb img{width:100%;height:100%;object-fit:cover}
.service-icon{width:50px;height:50px;margin:-25px 0 0 12px;position:relative}
.service-content{padding:8px 12px 0}
.card-title{margin:0;font-size:20px;line-height:32px;font-weight:500;color:var(--card-text)}
.card-text{margin:0;min-height:96px;font-size:16px;line-height:32px;color:var(--card-text)}
.card-link{font-size:16px;line-height:32px;font-weight:500;color:var(--primary)}


.fitness-arts-section .section-image{max-width:540px}
.fitness-arts-section .section-content{max-width:590px}
.on-demand-section .section-content-sm{max-width:387px}
.events-section .section-content-sm{max-width:387px}
.events-section .section-image{max-width:793px;justify-self:end}

/* On demand */
.feature-list{margin:0 0 32px;padding:0;list-style:none}
.feature-list li{display:flex;align-items:center;gap:12px;margin-bottom:20px;font-size:20px;line-height:32px;font-weight:500;color:var(--white)}
.feature-list li::before{content:'✓';width:24px;height:24px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--primary);font-size:14px;line-height:1;color:var(--white)}
.mockup-wrap{min-height:396px;position:relative;display:flex;align-items:center;justify-content:center}
.macbook-img{max-width:692px;width:100%}.phone-img{width:158px;position:absolute;left:5%;bottom:12%}

/* FAQ */
.faq-list{display:flex;flex-direction:column;gap:12px}
.faq-item{border-radius:12px;background:var(--light);padding:20px 20px 20px 40px;transition:background .25s ease,box-shadow .25s ease,padding .25s ease}
.faq-item-open,.faq-item.is-active{background:var(--white);padding:30px 20px 30px 40px}
.faq-header{align-items:flex-start}
.faq-title{margin:8px 0;font-size:20px;line-height:24px;font-weight:500;color:var(--black)}
.faq-panel{display:grid;grid-template-rows:0fr;transition:grid-template-rows .28s ease}
.faq-panel > *{overflow:hidden}
.faq-item.is-active .faq-panel{grid-template-rows:1fr}
.faq-text{margin:12px 0 0;max-width:800px;font-size:16px;line-height:28px;color:var(--body)}
.faq-btn{flex:0 0 auto;width:40px;height:40px;border:0;border-radius:12px;background:var(--primary);font-size:28px;line-height:1;color:var(--white);cursor:pointer}

/* About */
.quote-card{min-height:296px;border-radius:12px;background:var(--primary);padding:20px 30px;color:var(--white);overflow:hidden}
.quote-symbol{font-size:72px;line-height:.8;opacity:.35}
.quote-text{margin:10px 0 20px;font-size:20px;line-height:32px;font-weight:500}.quote-author{margin:0;font-size:16px;line-height:19px;font-style:italic}

/* Video / certs / footer */
.video-card img{border-radius:12px}.video-title{margin:12px 0 0;font-size:24px;line-height:40px;font-weight:500;text-align:center}
.cert-carousel{width:100%;overflow:hidden}.cert-track{display:flex;align-items:center;gap:80px;width:max-content;animation:certScroll 32s linear infinite}.cert-carousel:hover .cert-track{animation-play-state:paused}.cert-slide{width:200px;height:200px;flex:0 0 200px;display:flex;align-items:center;justify-content:center}.cert-slide img{width:200px;height:200px;object-fit:contain}@keyframes certScroll{from{transform:translateX(0)}to{transform:translateX(calc(-50% - 40px))}}
.site-footer{padding:80px 0 24px;background-image:radial-gradient(420px 420px at 6% 100%,rgba(224,23,131,.14),transparent 66%),radial-gradient(420px 420px at 60% 100%,rgba(119,61,190,.14),transparent 66%),url('assets/images/Group 1-1.png');background-repeat:no-repeat;background-size:auto,auto,96px 190px;background-position:center,right 0 bottom 56px}.footer-grid{align-items:start}.footer-brand-col,.footer-links-col,.footer-services-col,.footer-cta-col{min-width:0}.footer-logo{width:285px;max-width:100%;margin-bottom:16px}.footer-text{margin:0 0 20px;font-size:16px;line-height:24px;color:var(--white)}.footer-heading{margin:0 0 24px;font-size:20px;line-height:24px;font-weight:600;color:var(--white)}.footer-list{margin:0;padding:0;list-style:none}.footer-list li{margin-bottom:20px;font-size:16px;line-height:19px;color:var(--white)}.footer-title{margin:0 0 20px;font-family:'Plus Jakarta Sans',sans-serif;font-size:40px;line-height:50px;font-weight:600;color:var(--white)}.footer-cta-text{max-width:387px;margin-bottom:24px}.social-icon{width:40px;height:40px;border-radius:12px;background:var(--primary);display:flex;align-items:center;justify-content:center}.social-icon img{width:24px;height:24px;object-fit:contain}.footer-line{height:1px;margin:60px 0 18px;border-radius:100px;background:#808080}.copyright{margin:0;text-align:center;font-size:12px;line-height:15px;color:#B3B3B3}

/*Inner Page*/
/* Hero Banner Typography */
.inner-hero-title {font-family: 'Poppins', sans-serif;font-size: 55px;line-height: 64px;font-weight: 500;}
.inner-hero-title-accent {
  color: #E81A7B;
}
.inner-hero-subtitle {font-family: 'Inter', sans-serif;font-size: 16px;line-height: 32px;font-weight: 400;color: var(--white);}
.inner-page-hero-bg {background-size: contain;background-position: center;background-repeat: no-repeat;}

@media(max-width:1023px){.hero-image{justify-content:center}.fitness-arts-section .section-image,.events-section .section-image{max-width:none;justify-self:stretch}.section-padding{padding:64px 0}.hero-title{font-size:44px;line-height:54px}.section-title{font-size:36px;line-height:46px}.phone-img{display:none}.cert-track{gap:40px;animation-duration:24s}.cert-slide,.cert-slide img{width:180px;height:180px;flex-basis:180px}

.trust-bar-grid{gap:40px}.trust-bar-location,.trust-bar-experience{flex:1 1 0}.trust-bar-text{font-size:17px;line-height:25px}
}
@media(max-width:767px){.section-padding{padding:50px 0}.site-header{height:auto;padding:12px 0}.logo-img{width:170px}.hero-title{font-size:36px;line-height:44px}.section-title{font-size:30px;line-height:38px}.theme-btn{min-height:46px;font-size:14px}.btn-icon{width:32px;height:32px}.service-card{height:auto;padding-bottom:20px}.faq-item,.faq-item-open,.faq-item.is-active{padding:20px}.faq-title{font-size:18px;line-height:24px}.cert-track{gap:28px}.cert-slide,.cert-slide img{width:150px;height:150px;flex-basis:150px}.site-footer{padding-top:50px}

.trust-bar-section{padding:24px 0}.trust-bar-grid{flex-direction:column;align-items:flex-start;gap:20px}.trust-bar-location,.trust-bar-experience{width:100%;flex:0 0 auto}.trust-bar-icon{width:44px;height:44px;flex-basis:44px}.trust-bar-icon-inner{width:38px;height:38px}.trust-bar-icon svg{width:20px;height:20px}.trust-bar-text{font-size:16px;line-height:24px}.trust-bar-watermark{right:-20px;width:100px;height:100px}
}
